  closeAllEditors(): void { this.closeInventoryEditor(); this.closePurchaseEditor(); this.closeReagentEditor(); this.closePaymentEditor(); this.closeExpenseEditor(); this.closeOutCaseEditor(); this.closeOutRateEditor(); this.closeOutVendorEditor(); }

  hasText(item:any, q:string, keys:string[]): boolean{ const s=(q||'').trim().toLowerCase(); if(!s) return true; return keys.some(k=>String(item?.[k] ?? '').toLowerCase().includes(s)); }
  inDateRange(date:any, from:string, to:string): boolean { const d=String(date||''); return (!from || d>=from) && (!to || d<=to); }
  filteredInventory(): any[]{ return this.inventory.filter(i=>this.hasText(i,this.stockSearch,['item_code','item_name','brand','category','hsn_code','unit','pack_unit','purchase_unit'])); }
  filteredInventoryByText(q:string): any[]{ return this.inventory.filter(i=>this.hasText(i,q,['item_code','item_name','brand','category','hsn_code','unit','pack_unit','purchase_unit'])).slice(0,20); }
  filteredVendors(q:string): any[]{ return this.vendors.filter(v=>this.hasText(v,q,['name','gstin','phone'])).slice(0,20); }
  filteredTests(q:string): any[]{ return this.tests.filter(t=>this.hasText(t,q,['code','name','test_name','display_name','report_name','search_keywords'])).slice(0,20); }
