  openOutCaseCreate(): void{ this.outCaseMode='create'; this.outCaseForm=this.emptyOutCaseForm(); this.outCaseTestQuery=''; this.outCaseVendorQuery=''; this.outCaseStep=1; this.clearDirty(); }
  editOutCase(c:any): void{ this.outCaseMode='edit'; this.outCaseForm={...c, test_id:+c.test_id, outsource_vendor_id:+c.outsource_vendor_id}; this.outCaseTestQuery=c.test_name; this.outCaseVendorQuery=c.vendor_name; this.outCaseStep=1; this.clearDirty(); }
  closeOutCaseEditor(): void{ this.outCaseMode='list'; this.outCaseForm=this.emptyOutCaseForm(); this.outCaseTestQuery=''; this.outCaseVendorQuery=''; this.outCaseStep=1; this.clearDirty(); }
