  openStockModal(name=''): void{ this.inventoryForm={active:true, maintain_batch:false, maintain_expiry:false, pack_size:1, item_name:name || '', effective_from:new Date().toISOString().slice(0,10), effective_to:''}; this.stockModalOpen=true; }
  closeStockModal(): void{ this.stockModalOpen=false; }
  async saveStockModal(): Promise<void>{ const savedList=await window.limsApi.saveInventoryItem?.(this.inventoryForm) || []; this.inventory=savedList; this.operationUnits=await window.limsApi.listOperationUnits?.() || []; this.operationBrands=await window.limsApi.listOperationBrands?.() || [];
    this.operationHsns=await window.limsApi.listOperationHsns?.() || []; const saved=savedList.find((i:any)=>String(i.item_name||'').toLowerCase()===String(this.inventoryForm.item_name||'').toLowerCase()) || savedList[savedList.length-1]; this.stockModalOpen=false; if(saved) this.selectPurchaseItem(saved); }
